                        <label for="snack-price">Estimated Price ($)</label>
                        <input type="number" id="snack-price" class="form-control" step="0.01" min="0" placeholder="e.g., 14.99" required>
                    </div>
                    <button type="submit" class="btn" style="width: 100%; margin-top: 5px;">Save Item</button>
                </form>
            </div>

