<script>
    // Initial sample data
    const defaultSnacks = [
        { id: 1, name: "Premium Coffee Pods", status: "Out of Stock", priority: "High", price: 24.99, buy: true },
        { id: 2, name: "Mixed Roasted Nuts (Bulk)", status: "Low Stock", priority: "High", price: 18.50, buy: true },
        { id: 3, name: "Sparkling Water 24-Pack", status: "Low Stock", priority: "Medium", price: 11.99, buy: true },
        { id: 4, name: "Granola Bars (Variety)", status: "Good", priority: "Medium", price: 9.49, buy: false },
        { id: 5, name: "Dark Chocolate Squares", status: "Good", priority: "Low", price: 14.25, buy: false }
    ];

    const defaultPreferences = [
        { name: "Sarah M.", pref: "Needs sugar-free options / Sparkling water" },
        { name: "David K.", pref: "Keeps the bulk mixed nuts on heavy rotation" },
        { name: "Alex P.", pref: "Prefers dark chocolate over milk chocolate" }
    ];

    // App state
    let snacks = JSON.parse(localStorage.getItem("office_snacks")) || [...defaultSnacks];
    let preferences = [...defaultPreferences];

    function saveState() {
        localStorage.setItem("office_snacks", JSON.stringify(snacks));
    }

    function getStatusBadgeClass(status) {
        if (status === "Out of Stock") return "badge-status-out";
        if (status === "Low Stock") return "badge-status-critical";
        return "badge-status-good";
    }

    function getPriorityBadgeClass(priority) {
        if (priority === "High") return "badge-high";
        if (priority === "Medium") return "badge-medium";
        return "badge-low";
    }

    function render() {
        // Sort items so High Priority / Out of stock items surface cleanly
        const priorityOrder = { "High": 3, "Medium": 2, "Low": 1 };
        const statusOrder = { "Out of Stock": 3, "Low Stock": 2, "Good": 1 };

        snacks.sort((a, b) => {
            if (priorityOrder[b.priority] !== priorityOrder[a.priority]) {
                return priorityOrder[b.priority] - priorityOrder[a.priority];
            }
            return statusOrder[b.status] - statusOrder[a.status];
        });

        const tbody = document.getElementById("inventory-tbody");
        tbody.innerHTML = "";

        let totalSpend = 0;
        let buyCount = 0;

        snacks.forEach(snack => {
            if (snack.buy) {
                totalSpend += snack.price;
                buyCount++;
            }

            const tr = document.createElement("tr");
            tr.innerHTML = `
                <td style="text-align: center;">
                    <label class="checkbox-container">
                        <input type="checkbox" ${snack.buy ? 'checked' : ''} onchange="toggleBuy(${snack.id})">
                    </label>
                </td>
                <td style="font-weight: 500;">${snack.name}</td>
                <td><span class="badge ${getStatusBadgeClass(snack.status)}">${snack.status}</span></td>
                <td><span class="badge ${getPriorityBadgeClass(snack.priority)}">${snack.priority}</span></td>
                <td>$${snack.price.toFixed(2)}</td>
                <td class="actions-cell">
                    <button class="btn btn-secondary btn-sm" onclick="deleteItem(${snack.id})">Delete</button>
                </td>
            `;
            tbody.appendChild(tr);
        });

        // Update metrics
        document.getElementById("total-items-to-buy").textContent = `${buyCount} item${buyCount === 1 ? '' : 's'}`;
        document.getElementById("total-estimated-spend").textContent = `$${totalSpend.toFixed(2)}`;

        // Render preferences
        const prefContainer = document.getElementById("pref-list-container");
        prefContainer.innerHTML = "";
        preferences.forEach(p => {
            const li = document.createElement("li");
            li.className = "pref-item";
            li.innerHTML = `
                <span class="teammate-name">${p.name}</span>
                <span class="teammate-pref">${p.pref}</span>
            `;
            prefContainer.appendChild(li);
        });
    }

    function toggleBuy(id) {
        const snack = snacks.find(s => s.id === id);
        if (snack) {
            snack.buy = !snack.buy;
            saveState();
            render();
        }
    }

    function deleteItem(id) {
        snacks = snacks.filter(s => s.id !== id);
        saveState();
        render();
    }

    function handleFormSubmit(e) {
        e.preventDefault();
        const nameInput = document.getElementById("snack-name");
        const statusInput = document.getElementById("snack-status");
        const priorityInput = document.getElementById("snack-priority");
        const priceInput = document.getElementById("snack-price");

        // Simple duplicate matching or create new
        const existingIndex = snacks.findIndex(s => s.name.toLowerCase() === nameInput.value.trim().toLowerCase());

        if (existingIndex > -1) {
            snacks[existingIndex].status = statusInput.value;
            snacks[existingIndex].priority = priorityInput.value;
            snacks[existingIndex].price = parseFloat(priceInput.value);
            // Default to checked if it's low stock or out of stock
            if (statusInput.value !== "Good") snacks[existingIndex].buy = true;
        } else {
            const newSnack = {
                id: Date.now(),
                name: nameInput.value.trim(),
                status: statusInput.value,
                priority: priorityInput.value,
                price: parseFloat(priceInput.value),
                buy: statusInput.value !== "Good"
            };
            snacks.push(newSnack);
        }

        saveState();
        render();
        document.getElementById("snack-form").reset();
    }

    function resetToDefaults() {
        snacks = [...defaultSnacks];
        saveState();
        render();
    }

    // Initialize layout
    render();
</script>

</body>
</html>
