    // Handoff Utility Actions
    function copyToClipboard() {
        const lines = ["=== BREAKROOM RESTOCK ORDER ==="];
        let total = 0;

        snacks.forEach(s => {
            if (s.buy) {
                lines.push(`• ${s.name} (${s.status}) - $${s.price.toFixed(2)}`);
                total += s.price;
            }
        });

        lines.push(`\nTotal Estimated Spend: $${total.toFixed(2)}`);

        navigator.clipboard.writeText(lines.join("\\n")).then(() => {
            showToast("Restock order copied to clipboard!");
        });
    }

    function exportToCSV() {
        let csvContent = "data:text/csv;charset=utf-8,Item Name,Stock Status,Priority,Estimated Price,Selected to Buy\\n";

        snacks.forEach(s => {
            csvContent += `"${s.name.replace(/"/g, '""')}",${s.status},${s.priority},$${s.price.toFixed(2)},${s.buy ? 'YES' : 'NO'}\\n`;
        });

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `breakroom_restock_${new Date().toISOString().split('T')[0]}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    function showToast(msg) {
        const toast = document.getElementById("toast-banner");
        toast.textContent = msg;
        toast.style.display = "block";
        setTimeout(() => { toast.style.display = "none"; }, 2500);
    }

    function resetToDefaults() {
        if(confirm("Reset entire inventory list to defaults?")) {
            localStorage.removeItem("office_snacks");
            snacks = [...defaultSnacks];
            clearForm();
            render();
        }
    }

    // Initialize layout
    render();
</script>

</body>
