<div class="toast" id="toast-banner">List copied to clipboard!</div>

<script>
    const defaultSnacks = [
        { id: 1, name: "Premium Coffee Pods", status: "Out of Stock", priority: "High", price: 24.99, buy: true },
        { id: 2, name: "Mixed Roasted Nuts (Bulk)", status: "Low Stock", priority: "High", price: 18.50, buy: true },
        { id: 3, name: "Sparkling Water 24-Pack", status: "Low Stock", priority: "Medium", price: 11.99, buy: true },
        { id: 4, name: "Granola Bars (Variety)", status: "Good", priority: "Medium", price: 9.49, buy: false },
        { id: 5, name: "Dark Chocolate Squares", status: "Good", priority: "Low", price: 14.25, buy: false }
    ];

    const defaultPreferences = [
        { id: 101, name: "Sarah M.", pref: "Needs sugar-free options", targetProduct: "Sparkling Water 24-Pack" },
        { id: 102, name: "David K.", pref: "Keeps the bulk mixed nuts on heavy rotation", targetProduct: "Mixed Roasted Nuts (Bulk)" },
        { id: 103, name: "Alex P.", pref: "Prefers dark chocolate over milk chocolate", targetProduct: "Dark Chocolate Squares" }
    ];

    let snacks = JSON.parse(localStorage.getItem("v3_snacks")) || [...defaultSnacks];
    let preferences = JSON.parse(localStorage.getItem("v3_prefs")) || [...defaultPreferences];

    function saveToStorage() {
        localStorage.setItem("v3_snacks", JSON.stringify(snacks));
        localStorage.setItem("v3_prefs", JSON.stringify(preferences));
    }

    function getStatusBadgeClass(status) {
        if (status === "Out of Stock") return "badge-status-out";
        if (status === "Low Stock") return "badge-status-critical";
        return "badge-status-good";
    }

    function getPriorityBadgeClass(priority) {
        if (priority === "High" || priority === "Critical Priority") return "badge-high";
        if (priority === "Medium") return "badge-medium";
        return "badge-low";
    }

    function render() {
        const voteMap = {};
        preferences.forEach(p => {
            if (p.targetProduct) {
                voteMap[p.targetProduct] = (voteMap[p.targetProduct] || 0) + 1;
            }
        });

        snacks.forEach(s => {
            s.votesCount = voteMap[s.name] || 0;

            if (s.priority === "High" && s.votesCount > 0) {
                s.displayPriority = "Critical Priority";
                s.score = 4;
            } else {
                s.displayPriority = s.priority;
                s.score = s.priority === "High" ? 3 : (s.priority === "Medium" ? 2 : 1);
            }
        });

        const statusWeight = { "Out of Stock": 3, "Low Stock": 2, "Good": 1 };
        snacks.sort((a, b) => {
            if (b.score !== a.score) return b.score - a.score;
            return statusWeight[b.status] - statusWeight[a.status];
        });

        const tbody = document.getElementById("inventory-tbody");
        tbody.innerHTML = "";
        let totalSpend = 0;
        let buyCount = 0;

        snacks.forEach(snack => {
            if (snack.buy) {
                totalSpend += snack.price;
                buyCount++;
            }

            const tr = document.createElement("tr");
            tr.innerHTML = `
                <td style="text-align: center;">
                    <label class="checkbox-container">
                        <input type="checkbox" ${snack.buy ? 'checked' : ''} onchange="toggleBuy(${snack.id})">
                    </label>
                </td>
                <td style="font-weight: 500;">${snack.name}</td>
                <td><span class="badge ${getStatusBadgeClass(snack.status)}">${snack.status}</span></td>
                <td>
                    <div class="priority-indicator">
                        <span class="badge ${getPriorityBadgeClass(snack.displayPriority)}">${snack.displayPriority}</span>
                        ${snack.votesCount > 0 ? `<span class="upvoted-label">★ +${snack.votesCount} Request${snack.votesCount > 1 ? 's' : ''}</span>` : ''}
                    </div>
                </td>
                <td>$${snack.price.toFixed(2)}</td>
                <td class="actions-cell">
                    <button class="btn btn-secondary btn-sm" onclick="populateSnackEdit(${snack.id})">Edit</button>
                    <button class="btn btn-secondary btn-sm" onclick="deleteSnack(${snack.id})">Delete</button>
                </td>
            `;
            tbody.appendChild(tr);
        });

        document.getElementById("total-items-to-buy").textContent = `${buyCount} item${buyCount === 1 ? '' : 's'}`;
        document.getElementById("total-estimated-spend").textContent = `$${totalSpend.toFixed(2)}`;

        const selectDropdown = document.getElementById("pref-target");
        selectDropdown.innerHTML = `<option value="">-- No Direct Match --</option>`;

        [...snacks].sort((a,b) => a.name.localeCompare(b.name)).forEach(s => {
            const opt = document.createElement("option");
            opt.value = s.name;
            opt.textContent = s.name;
            selectDropdown.appendChild(opt);
        });

        const prefContainer = document.getElementById("pref-list-container");
        prefContainer.innerHTML = "";

        preferences.forEach(p => {
            const li = document.createElement("li");
            li.className = "pref-item";
            li.innerHTML = `
                <div class="teammate-info">
                    <span class="teammate-name">${p.name}</span>
                    <span class="teammate-pref">${p.pref}</span>
                    ${p.targetProduct ? `<span class="target-tag" title="Matches: ${p.targetProduct}">🎯 ${p.targetProduct}</span>` : ''}
                </div>
                <div class="actions-cell" style="flex-shrink: 0; margin-top: 2px;">
                    <button class="btn btn-secondary btn-sm" onclick="populatePrefEdit(${p.id})">Edit</button>
                    <button class="btn btn-secondary btn-sm" onclick="deletePref(${p.id})">×</button>
                </div>
            `;
            prefContainer.appendChild(li);
        });
    }

    function toggleBuy(id) {
        const snack = snacks.find(s => s.id === id);
        if (snack) {
            snack.buy = !snack.buy;
            saveToStorage();
            render();
        }
    }

    function populateSnackEdit(id) {
        const snack = snacks.find(s => s.id === id);
        if (!snack) return;

        document.getElementById("snack-id").value = snack.id;
        document.getElementById("snack-name").value = snack.name;
        document.getElementById("snack-status").value = snack.status;
        document.getElementById("snack-priority").value = snack.priority;
        document.getElementById("snack-price").value = snack.price;

        document.getElementById("snack-form-title").textContent = "Edit Item";
        document.getElementById("snack-submit-btn").textContent = "Update Item";
        document.getElementById("snack-submit-btn").classList.add("btn-success");
        document.getElementById("snack-cancel-btn").style.display = "inline-block";

        document.getElementById("snack-name").focus();
    }

    function clearSnackForm() {
        document.getElementById("snack-id").value = "";
        document.getElementById("snack-form").reset();
        document.getElementById("snack-form-title").textContent = "Add New Item";
        document.getElementById("snack-submit-btn").textContent = "Save Item";
        document.getElementById("snack-submit-btn").classList.remove("btn-success");
        document.getElementById("snack-cancel-btn").style.display = "none";
    }

    function handleSnackSubmit(e) {
        e.preventDefault();
        const idInput = document.getElementById("snack-id").value;
        const nameInput = document.getElementById("snack-name").value.trim();
        const statusInput = document.getElementById("snack-status").value;
        const priorityInput = document.getElementById("snack-priority").value;
        const priceInput = parseFloat(document.getElementById("snack-price").value);

        if (idInput) {
            const index = snacks.findIndex(s => s.id == idInput);
            if (index > -1) {
                const oldName = snacks[index].name;
                preferences.forEach(p => { if (p.targetProduct === oldName) p.targetProduct = nameInput; });

                snacks[index].name = nameInput;
                snacks[index].status = statusInput;
                snacks[index].priority = priorityInput;
                snacks[index].price = priceInput;
                if (statusInput !== "Good" && !snacks[index].buy) snacks[index].buy = true;
            }
        } else {
            const existingIndex = snacks.findIndex(s => s.name.toLowerCase() === nameInput.toLowerCase());
            if (existingIndex > -1) {
                snacks[existingIndex].status = statusInput;
                snacks[existingIndex].priority = priorityInput;
                snacks[existingIndex].price = priceInput;
                if (statusInput !== "Good") snacks[existingIndex].buy = true;
            } else {
                snacks.push({
                    id: Date.now(),
                    name: nameInput,
                    status: statusInput,
                    priority: priorityInput,
                    price: priceInput,
                    buy: statusInput !== "Good"
                });
            }
        }
        saveToStorage();
        render();
        clearSnackForm();
    }

    function deleteSnack(id) {
        const snack = snacks.find(s => s.id === id);
        if (snack && confirm(`Delete "${snack.name}"? This breaks active preference links.`)) {
            if (document.getElementById("snack-id").value == id) clearSnackForm();
            preferences.forEach(p => { if (p.targetProduct === snack.name) p.targetProduct = ""; });
            snacks = snacks.filter(s => s.id !== id);
            saveToStorage();
            render();
        }
    }

    function populatePrefEdit(id) {
        const p = preferences.find(pref => pref.id === id);
        if (!p) return;

        document.getElementById("pref-id").value = p.id;
        document.getElementById("pref-user").value = p.name;
        document.getElementById("pref-target").value = p.targetProduct || "";
        document.getElementById("pref-note").value = p.pref;

        document.getElementById("pref-form-title").textContent = "Edit Request";
        document.getElementById("pref-submit-btn").textContent = "Update Request";
        document.getElementById("pref-submit-btn").classList.add("btn-success");
        document.getElementById("pref-cancel-btn").style.display = "inline-block";
    }

    function clearPrefForm() {
        document.getElementById("pref-id").value = "";
        document.getElementById("pref-form").reset();
        document.getElementById("pref-form-title").textContent = "Add Teammate Request";
        document.getElementById("pref-submit-btn").textContent = "Save Request";
        document.getElementById("pref-submit-btn").classList.remove("btn-success");
        document.getElementById("pref-cancel-btn").style.display = "none";
    }

    function handlePrefSubmit(e) {
        e.preventDefault();
        const idInput = document.getElementById("pref-id").value;
        const userInput = document.getElementById("pref-user").value.trim();
        const targetInput = document.getElementById("pref-target").value;
        const noteInput = document.getElementById("pref-note").value.trim();

        if (idInput) {
            const idx = preferences.findIndex(p => p.id == idInput);
            if (idx > -1) {
                preferences[idx].name = userInput;
                preferences[idx].targetProduct = targetInput;
                preferences[idx].pref = noteInput;
            }
        } else {
            preferences.push({
                id: Date.now(),
                name: userInput,
                targetProduct: targetInput,
                pref: noteInput
            });
        }
        saveToStorage();
        render();
        clearPrefForm();
    }

    function deletePref(id) {
        if (document.getElementById("pref-id").value == id) clearPrefForm();
        preferences = preferences.filter(p => p.id !== id);
        saveToStorage();
        render();
    }

    function copyToClipboard() {
        const lines = ["=== BREAKROOM RESTOCK ORDER ==="];
        let total = 0;

        snacks.forEach(s => {
            if (s.buy) {
                const upvoteText = s.votesCount > 0 ? ` [Requested by ${s.votesCount}x]` : "";
                lines.push(`• ${s.name} (${s.status})${upvoteText} - $${s.price.toFixed(2)}`);
                total += s.price;
            }
        });

        lines.push(`\\nTotal Estimated Spend: $${total.toFixed(2)}`);

        navigator.clipboard.writeText(lines.join("\\n")).then(() => {
            showToast("Restock details copied to clipboard!");
        });
    }

    function exportToCSV() {
        let csvContent = "data:text/csv;charset=utf-8,Item Name,Stock Status,Base Priority,Teammate Requests Count,Estimated Price,Selected To Buy\\n";
        snacks.forEach(s => {
            csvContent += `"${s.name.replace(/"/g, '""')}",${s.status},${s.priority},${s.votesCount},$${s.price.toFixed(2)},${s.buy ? 'YES' : 'NO'}\\n`;
        });

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `breakroom_restock.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    function showToast(msg) {
        const toast = document.getElementById("toast-banner");
        toast.textContent = msg;
        toast.style.display = "block";
        setTimeout(() => { toast.style.display = "none"; }, 2500);
    }

    function resetToDefaults() {
        if(confirm("Wipe workspace and reset to preloaded layout templates?")) {
            localStorage.removeItem("v3_snacks");
            localStorage.removeItem("v3_prefs");
            snacks = [...defaultSnacks];
            preferences = [...defaultPreferences];
            clearSnackForm();
            clearPrefForm();
            render();
        }
    }

    render();
</script>

</body>
</html>
